def transform(grid):
    """Composite patterns with color priority 5 > 4 > 8 > 2."""
    w = len(grid[0])
    bands = [grid[i:i + 3] for i in range(0, len(grid), 3)]
    out = [[0] * w for _ in range(3)]
    for r in range(3):
        for c in range(w):
            for color in (5, 4, 8, 2):
                if any(band[r][c] == color for band in bands):
                    out[r][c] = color
                    break
    return out

